// Screen 20 of 29. Generated by Google Stitch, source folder 20-capture_complete.
// Rebuilt 3 August 2026. The generated version showed four grey rectangles
// labelled "Room 1" to "Room 4" and a Done button with an empty handler.
//
// It now shows the real evidence for this capture, INCLUDING SKIPPED ROOMS.
// A skip is deliberately visible here rather than hidden: it is recorded, it
// is shared with the host, and it counts against whoever skipped it if there
// is ever a claim. The guest should leave this screen knowing exactly what was
// and was not photographed.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import '../models/stay_enums.dart';
import '../models/stay_evidence.dart';
import '../theme/stay_colors.dart';

class CaptureCompleteScreen extends StatelessWidget {
  const CaptureCompleteScreen({
    super.key,
    this.evidence = const [],
    this.kind = CaptureKind.guestCheckIn,
    this.onDone,
  });

  /// Everything captured for this phase, from StayEvidenceService.watchKind.
  final List<StayEvidence> evidence;

  final CaptureKind kind;
  final VoidCallback? onDone;

  List<StayEvidence> get _photos =>
      evidence.where((e) => !e.skipped).toList(growable: false);
  List<StayEvidence> get _skipped =>
      evidence.where((e) => e.skipped).toList(growable: false);

  @override
  Widget build(BuildContext context) {
    final isCheckOut = kind == CaptureKind.guestCheckOut;

    return Scaffold(
      backgroundColor: GoOutsColors.cardSurface,
      body: SafeArea(
        child: Column(
          children: [
            const SizedBox(height: 24),
            const Icon(Icons.check_circle,
                color: GoOutsColors.success, size: 72),
            const SizedBox(height: 12),
            Text(
              isCheckOut ? 'Check out photos done' : 'Check in photos done',
              style: GoogleFonts.inter(
                fontSize: 20,
                height: 28 / 20,
                // w700, not `bold`. Same weight, one name — `bold` is how a
                // w800 crept back into three screens on the last pass.
                fontWeight: FontWeight.w700,
                color: GoOutsColors.deepNavy,
              ),
            ),
            const SizedBox(height: 4),
            Text(
              _photos.isEmpty
                  ? 'Nothing was photographed'
                  : 'Sent to your host',
              style: GoogleFonts.inter(color: GoOutsColors.bodyText),
            ),
            const SizedBox(height: 20),
            Expanded(
              child: _photos.isEmpty && _skipped.isEmpty
                  ? _empty()
                  : ListView(
                      padding: const EdgeInsets.symmetric(horizontal: 20),
                      children: [
                        if (_photos.isNotEmpty) _grid(),
                        if (_skipped.isNotEmpty) _skippedSection(),
                        const SizedBox(height: 16),
                        _whatHappensNext(isCheckOut),
                        const SizedBox(height: 12),
                        _lockedNote(),
                      ],
                    ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(20, 12, 20, 24),
              child: ElevatedButton(
                onPressed: onDone ?? () => Navigator.of(context).maybePop(),
                style: ElevatedButton.styleFrom(
                  backgroundColor: GoOutsColors.primaryBlue,
                  foregroundColor: GoOutsColors.cardSurface,
                  // 52, not 54. The Stitch spacing scale has one button
                  // height and this screen had drifted two pixels off it.
                  minimumSize: const Size(double.infinity, 52),
                  elevation: 0,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                child: Text(
                  'Done',
                  // button-text is 16/600. This was 15/bold, which is a size
                  // the scale does not use for a button and a weight written
                  // by its other name.
                  style: GoogleFonts.inter(
                      fontSize: 16, height: 24 / 16,
                      fontWeight: FontWeight.w600),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _empty() => Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Text(
            'No photographs were recorded for this stay.',
            textAlign: TextAlign.center,
            style: GoogleFonts.inter(
                fontSize: 14, color: GoOutsColors.bodyText),
          ),
        ),
      );

  Widget _grid() => GridView.builder(
        shrinkWrap: true,
        physics: const NeverScrollableScrollPhysics(),
        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: 2,
          crossAxisSpacing: 12,
          mainAxisSpacing: 12,
          childAspectRatio: 1.1,
        ),
        itemCount: _photos.length,
        itemBuilder: (context, i) => _thumb(_photos[i]),
      );

  Widget _thumb(StayEvidence e) => Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: e.url.isEmpty
                  ? Container(color: GoOutsColors.dividerGray)
                  : Image.network(
                      e.url,
                      fit: BoxFit.cover,
                      width: double.infinity,
                      // Decoded at thumbnail size. A grid of full resolution
                      // decodes is exactly how this screen would eat memory.
                      cacheWidth: 400,
                      errorBuilder: (_, __, ___) => Container(
                        color: GoOutsColors.dividerGray,
                        child: const Icon(Icons.broken_image_outlined,
                            color: GoOutsColors.outlineVariant),
                      ),
                    ),
            ),
          ),
          const SizedBox(height: 4),
          Text(
            // Through the label map, or the damage entry renders as
            // "__existing_damage" under its own photograph.
            stayRoomLabel(e.room),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: GoogleFonts.inter(
              fontSize: 12,
              fontWeight: FontWeight.w600,
              color: GoOutsColors.deepNavy,
            ),
          ),
        ],
      );

  Widget _skippedSection() => Padding(
        padding: const EdgeInsets.only(top: 20),
        child: Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: GoOutsColors.pageBackground,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                _skipped.length == 1 ? 'One room skipped' : 'Rooms skipped',
                style: GoogleFonts.inter(
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                  color: GoOutsColors.deepNavy,
                ),
              ),
              const SizedBox(height: 8),
              for (final s in _skipped)
                Padding(
                  padding: const EdgeInsets.only(bottom: 6),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Icon(Icons.remove_circle_outline,
                          size: 16, color: GoOutsColors.outlineVariant),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          s.skipReason == null || s.skipReason!.isEmpty
                              ? s.room
                              : '${s.room}. ${s.skipReason}',
                          style: GoogleFonts.inter(
                              fontSize: 13.5, color: GoOutsColors.bodyText),
                        ),
                      ),
                    ],
                  ),
                ),
              const SizedBox(height: 4),
              Text(
                'Skips are recorded and shared with your host, so the record '
                'is fair to both of you.',
                style: GoogleFonts.inter(
                    fontSize: 12, color: GoOutsColors.bodyText),
              ),
            ],
          ),
        ),
      );

  /// What happens to these photographs now.
  ///
  /// ── ⚠ NOT THE STITCH WORDING, AND DELIBERATELY ───────────────────────────
  ///
  /// Stitch says "Your host will review these captures within 24 hours. You'll
  /// receive a notification once the stay is fully confirmed."
  ///
  /// Both halves of that are untrue of this system. NOTHING requires a host to
  /// look at these, there is no 24 hour review, and no notification is sent
  /// when they do. What actually exists is stay_config's claimWindowHours,
  /// which is 72, and stay_claims.js which enforces it: after 72 hours from
  /// check out a host cannot open a claim at all.
  ///
  /// So the honest version is better for the guest anyway — it tells them the
  /// date they are in the clear, rather than promising them an inspection that
  /// nobody performs.
  ///
  /// ⚠ THE 72 IS ALSO IN stay_booking.dart AS claimWindowCloses AND IN
  /// stay_config.js AS claimWindowHours. If it changes, it changes in all
  /// three or this screen starts lying.
  Widget _whatHappensNext(bool isCheckOut) => Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: GoOutsColors.infoBlueBg,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Icon(Icons.info_outline,
                size: 16, color: GoOutsColors.primaryBlue),
            const SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    'What happens now',
                    style: GoogleFonts.inter(
                      fontSize: 13.5,
                      fontWeight: FontWeight.w700,
                      color: GoOutsColors.primaryBlue,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    isCheckOut
                        ? 'Your host has 72 hours from check out to raise a '
                            'damage claim. After that the stay is closed and '
                            'nothing can be claimed against it.'
                        : 'Your host can see these straight away. They are '
                            'what you would point to if a claim were ever '
                            'made about the state you found the place in.',
                    style: GoogleFonts.inter(
                      fontSize: 12,
                      height: 1.45,
                      color: GoOutsColors.bodyText,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      );

  Widget _lockedNote() => Row(
        children: [
          const Icon(Icons.lock_outline,
              size: 15, color: GoOutsColors.outlineVariant),
          const SizedBox(width: 6),
          Expanded(
            child: Text(
              'Nobody can edit or delete these, including us.',
              style: GoogleFonts.inter(
                  fontSize: 12, color: GoOutsColors.bodyText),
            ),
          ),
        ],
      );
}
